    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700;800&display=swap" rel="stylesheet">
    <style>
        body {
            font-family: 'Inter', sans-serif;
            background-color: #4a0e0e; /* Fallback */
        }

        .hero-bg {
            background: radial-gradient(circle at 80% 20%, #8B3A3A 0%, #4a0e0e 60%);
        }

        /* Card Stack Logic */
        .card-stack-container {
            perspective: 1200px;
            transform-style: preserve-3d;
        }

        .project-card {
            position: absolute;
            width: 100%;
            height: 100%;
            border-radius: 1.5rem;
            overflow: hidden;
            box-shadow: 0 20px 50px -12px rgba(0, 0, 0, 0.6);
            transition: all 0.5s cubic-bezier(0.25, 1, 0.5, 1);
            transform-origin: center bottom;
            cursor: pointer;
            border: 4px solid #F59E0B; /* Gold border */
            background: white;
        }

        /* Initial Stacked State (Collapsed) */
        .project-card:nth-child(1) {
            transform: translateY(0) scale(1);
            z-index: 10;
        }
        .project-card:nth-child(2) {
            transform: translateY(-40px) scale(0.95);
            z-index: 20;
        }
        .project-card:nth-child(3) {
            transform: translateY(-80px) scale(0.9);
            z-index: 30;
        }

        /* Hover State (Fan Out / Expand) */
        .card-stack-container:hover .project-card:nth-child(1) {
            transform: translateX(-20%) translateY(40px) rotate(-5deg) scale(0.95);
            z-index: 10;
            opacity: 0.7;
        }
        .card-stack-container:hover .project-card:nth-child(2) {
            transform: translateX(0%) translateY(0) rotate(0deg) scale(1);
            z-index: 30;
            opacity: 1;
            box-shadow: 0 30px 60px -15px rgba(0, 0, 0, 0.7);
        }
        .card-stack-container:hover .project-card:nth-child(3) {
            transform: translateX(20%) translateY(-40px) rotate(5deg) scale(0.95);
            z-index: 10;
            opacity: 0.7;
        }

        /* Specific content visibility adjustments on hover if needed, 
           but opacity handles the focus well enough for this demo */

        .badge-star {
            animation: pulse 2s infinite;
        }

        @keyframes pulse {
            0% { transform: scale(1); }
            50% { transform: scale(1.05); }
            100% { transform: scale(1); }
        }

        .text-gold { color: #FBBF24; }
        .bg-gold { background-color: #D97706; } 
        .btn-primary { background-color: #D97706; transition: all 0.3s ease; }
        .btn-primary:hover { background-color: #B45309; transform: translateY(-2px); }
        .btn-outline { border: 1px solid rgba(255,255,255,0.3); transition: all 0.3s ease; }
        .btn-outline:hover { background-color: rgba(255,255,255,0.1); border-color: white; }
    </style>
</head>
